4. Add tests to src/data-loader.test.ts
Add these tests within the deduplication describe block (after line 331):
test("should keep the oldest entry when duplicates are found", async () => {
	const olderData = {
		timestamp: "2024-01-01T00:00:00Z", // Earlier timestamp
		message: {
			usage: { input_tokens: 100, output_tokens: 50 },
			id: "msg123",
		},
		requestId: "req456",
		costUSD: 0.01,
	};

	const newerData = {
		timestamp: "2024-01-01T12:00:00Z", // Later timestamp
		message: {
			usage: { input_tokens: 200, output_tokens: 100 }, // Different token counts
			id: "msg123", // Same message ID
		},
		requestId: "req456", // Same request ID
		costUSD: 0.02, // Different cost
	};

	await using fixture = await createFixture({
		projects: {
			project1: {
				session1: {
					"a-first.jsonl": JSON.stringify(olderData), // File that should be processed first
					"b-second.jsonl": JSON.stringify(newerData), // File that should be processed second
				},
			},
		},
	});

	const dailyResult = await loadDailyUsageData({ claudePath: fixture.path });
	const sessionResult = await loadSessionData({ claudePath: fixture.path });

	// Daily aggregation should use older data
	expect(dailyResult).toHaveLength(1);
	expect(dailyResult[0]?.inputTokens).toBe(100); // From older entry
	expect(dailyResult[0]?.outputTokens).toBe(50); // From older entry
	expect(dailyResult[0]?.totalCost).toBe(0.01); // From older entry

	// Session data should also reflect older data
	expect(sessionResult).toHaveLength(1);
	expect(sessionResult[0]?.inputTokens).toBe(100); // From older entry
	expect(sessionResult[0]?.outputTokens).toBe(50); // From older entry
	expect(sessionResult[0]?.totalCost).toBe(0.01); // From older entry
	expect(sessionResult[0]?.lastActivity).toBe("2024-01-01"); // Should be from the older timestamp
});

test("should process files in chronological order based on first timestamp", async () => {
	// Create files with UUIDs that would sort differently than chronological order
	const file1Data = {
		timestamp: "2024-01-05T00:00:00Z", // Newer
		message: {
			usage: { input_tokens: 100, output_tokens: 50 },
			id: "msg123",
		},
		requestId: "req456",
		costUSD: 0.01,
	};

	const file2Data = {
		timestamp: "2024-01-01T00:00:00Z", // Older
		message: {
			usage: { input_tokens: 200, output_tokens: 100 },
			id: "msg123", // Same message
		},
		requestId: "req456", // Same request
		costUSD: 0.02,
	};

	await using fixture = await createFixture({
		projects: {
			project1: {
				// UUID starting with 'a' would normally be processed first
				"aaaa1111-1111-1111-1111-111111111111": {
					"usage.jsonl": JSON.stringify(file1Data), // But contains newer data
				},
				// UUID starting with 'z' would normally be processed last
				"zzzz9999-9999-9999-9999-999999999999": {
					"usage.jsonl": JSON.stringify(file2Data), // But contains older data
				},
			},
		},
	});

	const result = await loadDailyUsageData({ claudePath: fixture.path });

	// Should have kept the older entry (from zzzz file) despite it being alphabetically last
	expect(result).toHaveLength(1);
	expect(result[0]?.inputTokens).toBe(200); // From the older file2Data
	expect(result[0]?.outputTokens).toBe(100); // From the older file2Data
	expect(result[0]?.totalCost).toBe(0.02); // From the older file2Data
});
Note on Dependencies
No new dependencies are required. The solution uses only existing imports already present in the file.

